   [33]={next_id=34, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可以到我身边来吗，泽菲琳？", msg_color="", msg_size=0, talker="维拉提亚教皇", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [34]={next_id=35, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她默默地点头，一步一步地走上阶梯，来到教皇的身边。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
