   [36]={next_id=37, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="教皇大人，你怎么会变成这样……", msg_color="", msg_size=0, talker="泽菲琳", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7173", 0, 0, -14.5, 217}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [37]={next_id=38, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="因为我和你一样，孩子，我们都被绑在天兆之星为我们做好的命运线上，这是我终将会走到的一步。", msg_color="", msg_size=0, talker="维拉提亚教皇", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [38]={next_id=39, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="事到如今，或许你已经知道自己的特殊了，对吗？", msg_color="", msg_size=0, talker="维拉提亚教皇", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [39]={next_id=40, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……", msg_color="", msg_size=0, talker="泽菲琳", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7173", 0, 0, -14.5, 217}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [40]={next_id=41, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="泽菲琳想起了那趟列车和链尉官；想起了自己梦中的旋梯，那个牵着自己手的女人；想起了那些称自己为圣灵之子的人，他们看待自己的眼神如同狂信徒见到了降临的神明。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [41]={next_id=42, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="可在那一切还未发生之前，她只是一个普通的女孩，为了离开星都而绞尽脑汁。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [42]={next_id=43, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="他们说……我不是人类，我是被创造出来的“容器”。", msg_color="", msg_size=0, talker="泽菲琳", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7173", 0, 0, -14.5, 217}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [43]={next_id=44, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你是人类，泽菲琳。", msg_color="", msg_size=0, talker="维拉提亚教皇", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [44]={next_id=45, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你爱的人，爱你的人，他们都毫不怀疑。", msg_color="", msg_size=0, talker="维拉提亚教皇", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [45]={next_id=46, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="教皇的声音像春日溪水般柔和，她吃力地拉起女孩的手，慢慢抚慰着女孩。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [46]={next_id=47, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="……曾经，我见过你的母亲。在她临终前的片刻，我就在病床的旁边。", msg_color="", msg_size=0, talker="维拉提亚教皇", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [47]={next_id=48, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你母亲的离开……并非是因为重病。", msg_color="", msg_size=0, talker="维拉提亚教皇", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [48]={next_id=49, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="妈妈不是因为生病去世的……？可是我问了好多医生，他们都说妈妈得的是绝症……", msg_color="", msg_size=0, talker="泽菲琳", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7173", 0, 0, -14.5, 217}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [49]={next_id=50, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="普通的人类无法察觉“规则”的力量，你的母亲，是因天兆之星设下的规则而死。", msg_color="", msg_size=0, talker="维拉提亚教皇", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [50]={next_id=51, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="——身为封禁物碎片，它的“容器”，应该遵守的规则。", msg_color="", msg_size=0, talker="维拉提亚教皇", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [51]={next_id=52, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="望着泽菲琳似懂非懂的神情，教皇轻轻挥手，教皇厅的穹顶变得透明，露出了外面的样子。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [52]={next_id=53, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="那些被金色丝线缠绕的人影再度出现，告诉女孩，她刚刚做的不是梦。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [53]={next_id=54, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这些被缠绕住的信徒，他们的血肉已经化作天兆之星生长的养分。", msg_color="", msg_size=0, talker="维拉提亚教皇", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [54]={next_id=55, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="而他们的灵魂——或者说是残留的意识碎片，被天兆之星抽走，成为它侵入现实世界的爪牙。", msg_color="", msg_size=0, talker="维拉提亚教皇", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [55]={next_id=56, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="天兆之星就是这样筛选着维拉提亚的人类，为他们编造一个个终会登入“神国”的剧本。", msg_color="", msg_size=0, talker="维拉提亚教皇", audio="", img="arts/ui/bg/story/storybg_12_103.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
