   [88]={next_id=89, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="阻断天兆之星掠夺你的那一刻，是你将他带到了属于你的领域，保护着他。", msg_color="", msg_size=0, talker="维拉提亚教皇", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [89]={next_id=90, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我的……领域……？", msg_color="", msg_size=0, talker="泽菲琳", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7173", 0, 0, -14.5, 217}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [90]={next_id=91, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="如同这座教皇厅，我将你从天兆之星的神国里带来这里，能够隔绝天兆之星对你的搜寻。", msg_color="", msg_size=0, talker="维拉提亚教皇", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [91]={next_id=92, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我们是天兆之星封禁物碎片的化身，因此我们也继承了它的部分力量。", msg_color="", msg_size=0, talker="维拉提亚教皇", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [92]={next_id=93, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我们本应该被天兆之星回收，融合成它最终“完美”的躯体——但链尉官出现了，他强行打断了融合的进程。", msg_color="", msg_size=0, talker="维拉提亚教皇", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [93]={next_id=94, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="如今，我们的意志伴随着被分割的力量，与它的“神国”同处于一片空间中。", msg_color="", msg_size=0, talker="维拉提亚教皇", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [94]={next_id=95, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="天兆之星被阻拦了计划，它不会轻易放过链尉官，而链尉官是这个世界里唯一的“人类”，他无法在这个世界存活……", msg_color="", msg_size=0, talker="维拉提亚教皇", audio="", img="arts/ui/bg/story/storybg_ACT203_107.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7152_1", 0, 0, 31, 175.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
